        expected.put("lineCount", 1);
        expected.put("VowelCount", 3);
        expected.put("ConsonantCount", 7);
        expected.put("RepeatedWords", java.util.Collections.emptyList());
        when(textService.stats(input)).thenReturn(expected);

        // WHEN
